INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Fehlermanagement ein wichtiger Bestandteil der Projektorganisation?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Qualität"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Fehlermanagement?', 3, '[{"text": "Fehler früh erkennen und beheben", "correct": true, "because": "Minimiert Risiken"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlermanagement verbessert die Qualität. b) Es wird nur im Abschluss genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, durchgehend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Fehlermanagement?', 4, '[{"text": "Fehlererkennung", "correct": true, "because": "Identifiziert Probleme"}, {"text": "Unklare Prozesse", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Fehlerbehebung", "correct": true, "because": "Löst Probleme"}, {"text": "Dokumentation", "correct": true, "because": "Sichert Nachverfolgung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Fehlermanagement erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität leidet"}, {"text": "Ja", "correct": false, "because": "Risiken steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Fehlermanagement in der Durchführung?', 3, '[{"text": "Fehler während der Arbeit beheben", "correct": true, "because": "Sichert Fortschritt"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Team neu einteilen", "correct": false, "because": "Projektleiteraspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Fehlermanagement nur für IT-Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zum Fehlermanagement?', 3, '[{"text": "Fehler systematisch erfassen", "correct": true, "because": "Fördert Behebung"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlermanagement minimiert Risiken. b) Es ist immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Fehlermanagement?', 3, '[{"text": "Fehler häufen sich an", "correct": true, "because": "Keine Kontrolle"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Qualität steigt", "correct": false, "because": "Qualität leidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Fehlermanagement ohne Prozesse funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur nötig"}, {"text": "Ja", "correct": false, "because": "Unsystematisch unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Fehlermanagement?', 3, '[{"text": "Fehler in Ticket erfassen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas beheben", "correct": false, "because": "Zu vage"}, {"text": "Team soll Fehler ignorieren", "correct": false, "because": "Kein Management"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Fehlermanagement nur für die Durchführung relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Planung und Abschluss"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein effektives Fehlermanagement?', 4, '[{"text": "Systematische Erfassung", "correct": true, "because": "Fördert Übersicht"}, {"text": "Unklare Verantwortung", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Schnelle Reaktion", "correct": true, "because": "Minimiert Schäden"}, {"text": "Nachverfolgbarkeit", "correct": true, "because": "Sichert Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Fehlermanagement dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis und Lernen"}, {"text": "Nein", "correct": false, "because": "Dokumentation wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt Fehlermanagement?', 3, '[{"text": "Ticketsystem", "correct": true, "because": "Erfasst und verwaltet Fehler"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Fehlermanagement ohne Team funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Koordination nötig"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert Fehlermanagement?', 3, '[{"text": "Fehlende Kommunikation", "correct": true, "because": "Verhindert Behebung"}, {"text": "Klarer Prozess", "correct": false, "because": "Fördert Management"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlermanagement fördert Projekterfolg. b) Es ist nur für technische Fehler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Fehlermanagements?', 3, '[{"text": "Qualitätssicherung", "correct": true, "because": "Minimiert Probleme"}, {"text": "Maximale Fehler", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Behebung", "correct": false, "because": "Fördert Lösung"}]');
